type:
∀ {α : Type u_1} {β : Sort u_2} {M : List α → β} {L : GenLimit.Generic.Language α} {base : GenLimit.Generic.Stream α}
  {hbase : GenLimit.Generic.StreamIn base L}
  {hchange : ∀ (xs : List α), GenLimit.Angluin.ListWithin xs L → GenLimit.Angluin.HasChangeExtension M L xs} (n : ℕ),
  n ≤ (↑(GenLimit.Angluin.adversarialHistory M L base hbase hchange n)).length

∀ {α : Type u_1} {β : Sort u_2} {M : List α → β} {L : GenLimit.Generic.Language α} {base : GenLimit.Generic.Stream α}
  {hbase : GenLimit.Generic.StreamIn base L}
  {hchange : ∀ (xs : List α), GenLimit.Angluin.ListWithin xs L → GenLimit.Angluin.HasChangeExtension M L xs} (n : ℕ),
  have history := ↑(GenLimit.Angluin.adversarialHistory M L base hbase hchange n);
  have seeded := history ++ [base n];
  M ↑(GenLimit.Angluin.adversarialHistory M L base hbase hchange (n + 1)) ≠ M seeded

∀ {α : Type u_1} {β : Sort u_2} {M : List α → β} {L : GenLimit.Generic.Language α} {base : GenLimit.Generic.Stream α}
  {hbase : GenLimit.Generic.StreamIn base L}
  {hchange : ∀ (xs : List α), GenLimit.Angluin.ListWithin xs L → GenLimit.Angluin.HasChangeExtension M L xs} {n m : ℕ},
  n ≤ m →
    ↑(GenLimit.Angluin.adversarialHistory M L base hbase hchange n) <+:
      ↑(GenLimit.Angluin.adversarialHistory M L base hbase hchange m)

∀ {α : Type u_1} {β : Sort u_2} {M : List α → β} {L : GenLimit.Generic.Language α} {base : GenLimit.Generic.Stream α}
  {hbase : GenLimit.Generic.StreamIn base L}
  {hchange : ∀ (xs : List α), GenLimit.Angluin.ListWithin xs L → GenLimit.Angluin.HasChangeExtension M L xs} (n : ℕ),
  ↑(GenLimit.Angluin.adversarialHistory M L base hbase hchange n) <+:
    ↑(GenLimit.Angluin.adversarialHistory M L base hbase hchange (n + 1))

∀ {α : Type u_1} {β : Sort u_2} {M : List α → β} {L : GenLimit.Generic.Language α} {base : GenLimit.Generic.Stream α}
  {hbase : GenLimit.Generic.StreamIn base L}
  {hchange : ∀ (xs : List α), GenLimit.Angluin.ListWithin xs L → GenLimit.Angluin.HasChangeExtension M L xs} (n : ℕ)
  (state : GenLimit.Angluin.HistoryIn L),
  ↑(GenLimit.Angluin.adversarialStep M L base hbase hchange n state) =
    let seeded := ↑state ++ [base n];
    seeded ++ Classical.choose ⋯

∀ {α : Type u_1} {β : Sort u_2} {M : List α → β} {L : GenLimit.Generic.Language α} {base : GenLimit.Generic.Stream α}
  {hbase : GenLimit.Generic.StreamIn base L}
  {hchange : ∀ (xs : List α), GenLimit.Angluin.ListWithin xs L → GenLimit.Angluin.HasChangeExtension M L xs} (n k : ℕ)
  (hk : k < (↑(GenLimit.Angluin.adversarialHistory M L base hbase hchange n)).length),
  GenLimit.Angluin.adversarialStream M L base hbase hchange k =
    (↑(GenLimit.Angluin.adversarialHistory M L base hbase hchange n)).get ⟨k, hk⟩

∀ {α : Type u_1} [Nonempty α] [Countable α] {H : GenLimit.Generic.LanguageClass α}
  (E : GenLimit.Bridge.ClassEnumeration H),
  GenLimit.Angluin.ExtensionallyIdentifiable H ↔ GenLimit.Angluin.ExtensionalTellTaleCondition H

∀ {α : Type u_1} {β : Sort u_2} {M : List α → β} {L : GenLimit.Generic.Language α} {base : GenLimit.Generic.Stream α}
  {hbase : GenLimit.Generic.StreamIn base L}
  {hchange : ∀ (xs : List α), GenLimit.Angluin.ListWithin xs L → GenLimit.Angluin.HasChangeExtension M L xs} (n : ℕ),
  GenLimit.textPrefix (GenLimit.Angluin.adversarialStream M L base hbase hchange)
      (↑(GenLimit.Angluin.adversarialHistory M L base hbase hchange n)).length =
    ↑(GenLimit.Angluin.adversarialHistory M L base hbase hchange n)

∀ {α : Type u_1} {β : Sort u_2} {M : List α → β} {L : GenLimit.Generic.Language α} {base : GenLimit.Generic.Stream α}
  {hbase : GenLimit.Generic.StreamIn base L}
  {hchange : ∀ (xs : List α), GenLimit.Angluin.ListWithin xs L → GenLimit.Angluin.HasChangeExtension M L xs}
  {xs : List α} {n : ℕ},
  xs <+: ↑(GenLimit.Angluin.adversarialHistory M L base hbase hchange n) →
    GenLimit.textPrefix (GenLimit.Angluin.adversarialStream M L base hbase hchange) xs.length = xs

∀ {A : GenLimit.CharikarPabbaraju.TwoLanguageMembershipAlgorithm}
  {current : GenLimit.CharikarPabbaraju.FiniteDiagonalStage}
  (self : GenLimit.CharikarPabbaraju.CompletionDrivenStep A current),
  GenLimit.CharikarPabbaraju.AssignmentExtends current.assignment self.next.assignment

∀ {A : GenLimit.CharikarPabbaraju.TwoLanguageMembershipAlgorithm}
  {current : GenLimit.CharikarPabbaraju.FiniteDiagonalStage}
  (self : GenLimit.CharikarPabbaraju.CompletionDrivenStep A current),
  self.commonAssignment = GenLimit.CharikarPabbaraju.assignCommon current.assignment self.newInput

∀ {A : GenLimit.CharikarPabbaraju.TwoLanguageMembershipAlgorithm}
  {current : GenLimit.CharikarPabbaraju.FiniteDiagonalStage}
  (self : GenLimit.CharikarPabbaraju.CompletionDrivenStep A current),
  GenLimit.CharikarPabbaraju.ExecutionValid A self.temporaryLeft self.temporaryRight (current.inputs ++ [self.newInput])
    self.rounds

∀ {A : GenLimit.CharikarPabbaraju.TwoLanguageMembershipAlgorithm}
  {current : GenLimit.CharikarPabbaraju.FiniteDiagonalStage}
  (self : GenLimit.CharikarPabbaraju.CompletionDrivenStep A current), current.assignment self.newInput = none

∀ {A : GenLimit.CharikarPabbaraju.TwoLanguageMembershipAlgorithm}
  {current : GenLimit.CharikarPabbaraju.FiniteDiagonalStage}
  (self : GenLimit.CharikarPabbaraju.CompletionDrivenStep A current),
  self.next.assignment = GenLimit.CharikarPabbaraju.recordOutput self.queryAssignment self.output

∀ {A : GenLimit.CharikarPabbaraju.TwoLanguageMembershipAlgorithm}
  {current : GenLimit.CharikarPabbaraju.FiniteDiagonalStage}
  (self : GenLimit.CharikarPabbaraju.CompletionDrivenStep A current),
  self.next.inputs = current.inputs ++ [self.newInput]

∀ {A : GenLimit.CharikarPabbaraju.TwoLanguageMembershipAlgorithm}
  {current : GenLimit.CharikarPabbaraju.FiniteDiagonalStage}
  (self : GenLimit.CharikarPabbaraju.CompletionDrivenStep A current),
  ∃ (hlast : current.inputs.length < self.rounds.length),
    (self.rounds.get ⟨current.inputs.length, hlast⟩).2.2 = self.output

∀ {A : GenLimit.CharikarPabbaraju.TwoLanguageMembershipAlgorithm}
  {current : GenLimit.CharikarPabbaraju.FiniteDiagonalStage}
  (self : GenLimit.CharikarPabbaraju.CompletionDrivenStep A current),
  GenLimit.CharikarPabbaraju.PartialAssignmentDecidesExecution self.queryAssignment self.rounds

∀ {A : GenLimit.CharikarPabbaraju.TwoLanguageMembershipAlgorithm}
  {current : GenLimit.CharikarPabbaraju.FiniteDiagonalStage}
  (self : GenLimit.CharikarPabbaraju.CompletionDrivenStep A current),
  (GenLimit.CharikarPabbaraju.partialAssignmentDomain self.queryAssignment).Finite

∀ {A : GenLimit.CharikarPabbaraju.TwoLanguageMembershipAlgorithm}
  {current : GenLimit.CharikarPabbaraju.FiniteDiagonalStage}
  (self : GenLimit.CharikarPabbaraju.CompletionDrivenStep A current),
  self.queryAssignment =
    GenLimit.CharikarPabbaraju.recordExecutionAnswers self.commonAssignment self.temporaryLeft self.temporaryRight
