∀ {A : GenLimit.CharikarPabbaraju.TwoLanguageMembershipAlgorithm}
  {current : GenLimit.CharikarPabbaraju.FiniteDiagonalStage}
  (self : GenLimit.CharikarPabbaraju.CompletionDrivenStep A current),
  GenLimit.CharikarPabbaraju.partialAssignmentCommon self.queryAssignment ⊆
    GenLimit.CharikarPabbaraju.partialAssignmentCommon self.commonAssignment

∀ {A : GenLimit.CharikarPabbaraju.TwoLanguageMembershipAlgorithm}
  {current : GenLimit.CharikarPabbaraju.FiniteDiagonalStage}
  (self : GenLimit.CharikarPabbaraju.CompletionDrivenStep A current),
  self.temporaryLeft ∩ self.temporaryRight ⊆ GenLimit.CharikarPabbaraju.partialAssignmentCommon self.commonAssignment

∀ {A : GenLimit.CharikarPabbaraju.TwoLanguageMembershipAlgorithm}
  {current : GenLimit.CharikarPabbaraju.FiniteDiagonalStage}
  (self : GenLimit.CharikarPabbaraju.CompletionDrivenStep A current), self.temporaryLeft.Infinite

∀ {A : GenLimit.CharikarPabbaraju.TwoLanguageMembershipAlgorithm}
  {current : GenLimit.CharikarPabbaraju.FiniteDiagonalStage}
  (self : GenLimit.CharikarPabbaraju.CompletionDrivenStep A current),
