∀ {α : Type u_1} [inst : Countable α] {D : GenLimit.CharikarPabbaraju.ExhaustiveDiagonalProblem α} {i : ℕ}
  {P : GenLimit.CharikarPabbaraju.ExhaustiveDiagonalPrefix D}
  (self : GenLimit.CharikarPabbaraju.ExhaustiveDiagonalStep D i P), self.endpoint < self.next.length

∀ {α : Type u_1} [inst : Countable α] {D : GenLimit.CharikarPabbaraju.ExhaustiveDiagonalProblem α} {i : ℕ}
  {P : GenLimit.CharikarPabbaraju.ExhaustiveDiagonalPrefix D}
  (self : GenLimit.CharikarPabbaraju.ExhaustiveDiagonalStep D i P),
  (GenLimit.CharikarPabbaraju.generateOnly D.algorithm self.next.stream self.endpoint \ self.witness).Finite

∀ {α : Type u_1} [inst : Countable α] {D : GenLimit.CharikarPabbaraju.ExhaustiveDiagonalProblem α} {i : ℕ}
  {P : GenLimit.CharikarPabbaraju.ExhaustiveDiagonalPrefix D}
  (self : GenLimit.CharikarPabbaraju.ExhaustiveDiagonalStep D i P), P.length + 1 ≤ self.next.length

∀ {α : Type u_1} [inst : Countable α] {D : GenLimit.CharikarPabbaraju.ExhaustiveDiagonalProblem α} {i : ℕ}
  {P : GenLimit.CharikarPabbaraju.ExhaustiveDiagonalPrefix D}
