∀ {α : Type u_1} {L expanded : GenLimit.Generic.Language α}
  (self : GenLimit.InfiniteContamination.FiniteExpansionWitness L expanded),
  GenLimit.InfiniteContamination.finiteExpansion L self.add self.remove = expanded

∀ (setGen : GenLimit.InfiniteContamination.SetGenerator ℕ)
  (hinfinite : GenLimit.InfiniteContamination.IsInfiniteSetGenerator setGen)
  (selection : (t : ℕ) → (Fin t → ℕ) → Finset ℕ) (orders : ℕ → GenLimit.KleinbergWei.OrderedLanguage) (ρ : ℝ) (t : ℕ)
  (xs : Fin t → ℕ),
  GenLimit.InfiniteContamination.algorithmEightOutput setGen hinfinite selection orders ρ t xs =
    let previous :=
      Finset.image
        (fun s =>
          GenLimit.InfiniteContamination.algorithmEightOutput setGen hinfinite selection orders ρ ↑s fun j =>
            xs ⟨↑j, ⋯⟩)
        Finset.univ;
    let forbidden := GenLimit.Generic.sequenceSample xs ∪ previous;
    let A := GenLimit.InfiniteContamination.algorithmEightChosenSet setGen selection orders ρ xs;
    have hA := ⋯;
    have hexists := ⋯;
    Nat.find hexists

∀ {α : Type u_1} (family : ℕ → GenLimit.Generic.Language α) (threshold : ℕ → ℝ) (fallback : α) (t : ℕ) (xs : Fin t → α),
  GenLimit.InfiniteContamination.algorithmFourOutput family threshold fallback t xs =
    have selected := GenLimit.InfiniteContamination.algorithmFourHistoryIndices family threshold fallback xs;
    have previous :=
      Finset.image
        (fun s => GenLimit.InfiniteContamination.algorithmFourOutput family threshold fallback ↑s fun j => xs ⟨↑j, ⋯⟩)
        Finset.univ;
    have forbidden := GenLimit.Generic.sequenceSample xs ∪ previous;
    have core :=
      GenLimit.InfiniteContamination.finiteCommonCore (GenLimit.InfiniteContamination.indexedLanguages family selected);
    if h : ∃ x ∈ core, x ∉ forbidden then Classical.choose h else fallback

∀ {α : Type u_1} {stream : GenLimit.Generic.Stream α} {L : GenLimit.Generic.Language α}
  (hfinite : GenLimit.InfiniteContamination.FiniteNoise stream L) (n : ℕ),
