  GenLimit.NoisyExamples.noisyClosureStrategyOutput H hdim S t ∈ GenLimit.NoisyExamples.noisyCommonCore H S n \ ↑S

∀ {α : Type u_1} {classes : ℕ → GenLimit.Generic.LanguageClass α}
  {hdim : ∀ (i : ℕ), GenLimit.NoisyExamples.FiniteNoisyClosureDimensionAt (classes i) i} {S : Finset α} {t : ℕ}
  (hE : (GenLimit.NoisyExamples.diagonalEligibleIndices classes hdim S t).Nonempty),
  GenLimit.NoisyExamples.selectedDiagonalIndex classes hdim S t hE ∈
    GenLimit.NoisyExamples.diagonalEligibleIndices classes hdim S t

∀ {α : Type u_1} {H : GenLimit.Generic.LanguageClass α}
  {hdim : ∀ (n : ℕ), GenLimit.NoisyExamples.FiniteNoisyClosureDimensionAt H n} {S : Finset α} {t : ℕ}
  (hE : (GenLimit.NoisyExamples.eligibleNoiseLevels H hdim S t).Nonempty),
  GenLimit.NoisyExamples.selectedNoiseLevel H hdim S t hE ∈ GenLimit.NoisyExamples.eligibleNoiseLevels H hdim S t

∀ (O : GenLimit.OracleFamily) (state : GenLimit.OracleFamily.CarriedWitnessProtectionState) (x t : ℕ)
  (hactive :
    O.HasReplayActive
      (GenLimit.OracleFamily.witnessProtectionSureUpdate
        { sure := state.sure, pastOutputs := state.pastOutputs, output := state.output } x)
      t),
  O.carriedWitnessProtectionProcessRound state x t =
    let sure :=
      GenLimit.OracleFamily.witnessProtectionSureUpdate
        { sure := state.sure, pastOutputs := state.pastOutputs, output := state.output } x;
    have lower := GenLimit.OracleFamily.replayCarriedStart state x;
    have cutoff := O.replayCarriedRoundCutoff sure state.pastOutputs t lower hactive;
    have out := O.replayCarriedRoundOutput sure state.pastOutputs t lower hactive;
    { sure := sure, pastOutputs := insert out state.pastOutputs, cutoff := cutoff, output := out }

∀ (O : GenLimit.OracleFamily) (state : GenLimit.OracleFamily.WitnessProtectionState) (x t : ℕ)
  (hactive : O.HasReplayActive (GenLimit.OracleFamily.witnessProtectionSureUpdate state x) t),
  O.witnessProtectionProcessRound state x t =
    let sure := GenLimit.OracleFamily.witnessProtectionSureUpdate state x;
    have out := O.replayRoundOutput sure state.pastOutputs t hactive;
    { sure := sure, pastOutputs := insert out state.pastOutputs, output := out }

