∀ {α : Type u_1} {F : ℕ → Set α} {noise : ℕ → ℕ} {stage : ℕ}
  (self : GenLimit.ParetoGeneration.NoisyProcedureStage F noise stage),
  ∀ i < stage, ∀ j ∈ self.witness i, j ≠ i → j < i ∧ self.complexity j < self.complexity i

∀ {α : Type u_1} [inst : DecidableEq α] {F : ℕ → Set α} {noise complexity : ℕ → ℕ}
