  other ∈ certificate.witness coordinate →
    GenLimit.ParetoGeneration.NoiseContainedAt F noise other (certificate.witnessSet coordinate ∪ ⋯.toFinset)

∀ {α : Type u_1} {F : ℕ → Set α} {noise complexity : ℕ → ℕ}
