∀ {C : GenLimit.LanguageFamily} {stream : ℕ → ℕ} {t : ℕ} {old : GenLimit.PatientMachine.State},
  ¬(GenLimit.PatientMachine.consistentIndices C stream (t + 1) old.scope).Nonempty →
    (∃ i, GenLimit.Consistent C stream (t + 1) i) →
      GenLimit.PatientMachine.backtrackDecision C stream t old =
        have i := GenLimit.PatientMachine.lowestConsistent C stream (t + 1) old.focus;
        { scope := i + 1, tau := old.tau + 1, focus := i, move := GenLimit.PatientMachine.MoveKind.backtrack }

∀ {C : GenLimit.LanguageFamily} {stream : ℕ → ℕ} {t : ℕ} {old : GenLimit.PatientMachine.State},
  (GenLimit.PatientMachine.consistentIndices C stream (t + 1) old.scope).Nonempty →
    ¬(GenLimit.PatientMachine.survivingCriticalIndices C stream t old.scope).Nonempty →
      GenLimit.PatientMachine.backtrackDecision C stream t old =
        have i := GenLimit.PatientMachine.lowestConsistentInScope C stream (t + 1) old.scope old.focus;
        { scope := i + 1, tau := old.tau + 1, focus := i, move := GenLimit.PatientMachine.MoveKind.backtrack }

∀ {C : GenLimit.LanguageFamily} {stream : ℕ → ℕ} {t : ℕ} {old : GenLimit.PatientMachine.State},
  (GenLimit.PatientMachine.consistentIndices C stream (t + 1) old.scope).Nonempty →
    (GenLimit.PatientMachine.survivingCriticalIndices C stream t old.scope).Nonempty →
      GenLimit.PatientMachine.backtrackDecision C stream t old =
        have i := GenLimit.PatientMachine.highestSurvivor C stream t old.scope old.focus;
        { scope := i + 1, tau := old.tau + 1, focus := i, move := GenLimit.PatientMachine.MoveKind.backtrack }

∀ (C : GenLimit.LanguageFamily) (stream : ℕ → ℕ) (t : ℕ) (old : GenLimit.PatientMachine.State),
  have d := GenLimit.PatientMachine.decide C stream t old;
  d.tau = old.tau ∨ d.tau = old.tau + 1

∀ (C : GenLimit.LanguageFamily) (stream : ℕ → ℕ) (t : ℕ) (old : GenLimit.PatientMachine.State),
  have d := GenLimit.PatientMachine.stableDecision C stream t old;
  d.tau = old.tau ∨ d.tau = old.tau + 1

∀ (O : GenLimit.OracleFamily) (stream : ℕ → ℕ),
  Set.InjOn (fun d => (GenLimit.PatientMachine.run O stream d).tau)
    {d | ∃ i, GenLimit.PatientMachine.UpwardDeparture O stream i d}

